    `SELECT current_database() AS db, current_user AS user, current_role AS role,
            r.rolsuper AS superuser, r.rolbypassrls AS bypass_rls, r.rolcanlogin AS login
     FROM pg_roles r WHERE r.rolname = current_role`,
